def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a 3D DP array where dp[i][j][k] represents the maximum value collected
    # up to cell (i, j) while choosing cell (k, j) or (i, k)
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid_values[0][2]

    # Insert grid values into a dictionary for O(1) access
    grid = {(x, y): v for x, y, v in grid_values[:-1]}

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(N):
                if i == 0 and j == 0 and k == 0:
                    continue
                if (i, j) in grid:
                    value = grid[(i, j)]
                else:
                    value = 0

                # Choose the optimal path
                if i > 0 and j > 0 and k > 0:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1], dp[i-1][j-1][k], dp[i-1][j][k-1], dp[i][j-1][k-1], key=lambda x: x + value)
                elif i > 0 and j > 0:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i-1][j-1][k], key=lambda x: x + value)
                elif i > 0 and k > 0:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j][k-1], dp[i-1][j][k-1], key=lambda x: x + value)
                elif j > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j-1][k], dp[i][j][k-1], dp[i][j-1][k-1], key=lambda x: x + value)
                elif i > 0:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i-1][j][k-1], key=lambda x: x + value)
                elif j > 0:
                    dp[i][j][k] = max(dp[i][j-1][k], dp[i][j-1][k-1], key=lambda x: x + value)
                elif k > 0:
                    dp[i][j][k] = max(dp[i][j][k-1], dp[i][j-1][k-1], key=lambda x: x + value)

    # The bottom-right corner will have the maximum value collected by both paths
    return max(dp[N-1][N-1][i] for i in range(N))

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a 2D list to store the grid values
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize a 3D DP array to store the maximum values
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Fill the DP array
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j] = [grid[i][j], grid[i][j]]
            elif i == 0:
                dp[i][j] = [grid[i][j] + dp[i][j-1][0], grid[i][j] + dp[i][j-1][1]]
            elif j == 0:
                dp[i][j] = [grid[i][j] + dp[i-1][j][0], grid[i][j] + dp[i-1][j][1]]
            else:
                dp[i][j] = [
                    grid[i][j] + max(dp[i-1][j][0], dp[i][j-1][0]),
                    grid[i][j] + max(dp[i-1][j][1], dp[i][j-1][1])
                ]

    # The result is the maximum of the two possible sums at the bottom-right corner
    return max(dp[N-1][N-1])

