def cantor_numbering(N: int) -> str:
    denominator = 1
    numerator = 1
    step = 2
    while N > step - 1:
        N -= step - 1
        step += 2
        if step % 4 == 2:
            numerator += 1
        else:
            denominator += 1
    if step % 4 == 2 or step % 4 == 0:
        numerator += N
        denominator -= N
    else:
        numerator -= N
        denominator += N
    return f"{numerator}/{denominator}"

