def max_product(num_str: str, N: int, K: int) -> int:
    from itertools import combinations
    import functools

    def product_of_parts(parts: list) -> int:
        return functools.reduce(lambda x, y: x * y, [int(part) for part in parts])

    max_product_value = 0
    for positions in combinations(range(1, N), K):
        parts = []
        start = 0
        for pos in positions:
            parts.append(num_str[start:pos])
            start = pos
        parts.append(num_str[start:])
        max_product_value = max(max_product_value, product_of_parts(parts))

    return max_product_value

