    isbn_parts = isbn.split('-')
    isbn_numbers = isbn_parts[:3] + [isbn_parts[3] + calculate_checksum(isbn_parts[3] + recreate_checksum(isbn_parts[3]))] + isbn_parts[4:]
    correct_isbn = '-'.join(isbn_numbers)
    return "Right" if correct_isbn == isbn else correct_isbn

