        return int(digit) if digit != 'X' else 10

    def calculate_checksum(isbn):
        return sum((10 - i) * check_digit(isbn[i]) for i in range(10)) % 11

    isbn = isbn.strip()
    if len(isbn) != 13 or '-' not in isbn:
        raise ValueError("Invalid ISBN format")

    parts = isbn.split('-')
    if len(parts) != 4 or parts[0] != '0' or parts[3] not in '0123456789X':
        raise ValueError("Invalid ISBN format")

    if calculate_checksum(isbn) == 0:
        return "Right"
    else:
        corrected_digit = str(11 - calculate_checksum(isbn) % 11)
        return isbn[:-1] + corrected_digit

