    isbn_number = ''.join(isbn_parts[:3]) + isbn_parts[3][:-1]
    current_checksum = isbn_parts[3][-1]
    calculated_checksum = calculate_checksum(isbn_number)

    if current_checksum == str(calculated_checksum):
        return "Right"
    else:
        return isbn_number + '-' + str(calculated_checksum)

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            value = int(char) if char != 'X' else 10
            total += value * (10 - i)
        return total % 11

    parts = isbn.split('-')
    if len(parts) != 4 or len(parts[3]) != 1:
        raise ValueError("Invalid ISBN format")

    base_isbn = '-'.join(parts[:3])
    calculated_checksum = calculate_checksum(base_isbn)
    provided_checksum = int(parts[3])

    if calculated_checksum == provided_checksum:
        return "Right"
    else:
        corrected_isbn = f"{base_isbn}-{provided_checksum}"
        if calculated_checksum == 1:
            corrected_isbn = f"{base_isbn}-{10}"
        return corrected_isbn

