def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()
        if steps >= 10:
            break
        for old_sub, new_sub in rules:
            start = 0
            while start < len(current):
                start = current.find(old_sub, start)
                if start == -1:
                    break
                new_str = current[:start] + new_sub + current[start + len(old_sub):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start += 1

    return "NO ANSWER!"

