def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord(k) - 97 + 26) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord(k) - 65 + 26) % 26 + ord('A'))
        else:
            return c

    decrypted_text = []
    key_length = len(key)
    for i in range(len(ciphertext)):
        decrypted_text.append(shift_char(ciphertext[i], key[i % key_length]))
    return ''.join(decrypted_text)

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    plaintext = []
    for i in range(len(ciphertext)):
        key_char = key[i % key_length]
        key_index = ord(key_char.lower()) - ord('a')
        ciphertext_char = ciphertext[i]
        if ciphertext_char.isalpha():
            base = ord('a') if ciphertext_char.islower() else ord('A')
            plaintext_char = chr((ord(ciphertext_char) - base - key_index) % 26 + base)
            plaintext.append(plaintext_char)
        else:
            plaintext.append(ciphertext_char)
    return ''.join(plaintext)

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    plaintext = []
    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext.append(chr(value + 65))
    return ''.join(plaintext)

